import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { UserSessionService } from 'src/app/services/usersession.service';
import { ModalController, NavParams } from '@ionic/angular';
import { SqlitedatabaseService } from 'src/app/services/sqlite/sqlitedatabase.service';

@Component({
  selector: 'app-instruction',
  templateUrl: './instruction.page.html',
  styleUrls: ['./instruction.page.scss'],
})
export class InstructionPage implements OnInit {
  checkBox: any;
  count: number = 1;
  username: any;
  schoolID: any;
  sync: any;

  constructor(private router: Router, private usersessionService: UserSessionService, 
    private navParams: NavParams, private modalCtrl: ModalController,
    private sqliteDB: SqlitedatabaseService) { 
    this.username = this.usersessionService.emis_username(); 
    this.schoolID = this.navParams.get('schoolID');
    this.sync = this.navParams.get('sync');

  }

  ngOnInit() {
  }

  ionViewDidEnter() {
    console.log(this.sync,"this.sync");
    debugger
    this.checkBox = false;
    var checkValue = localStorage.getItem('checkValue')
    if (checkValue == '2') {
      localStorage.setItem('checkValue', '3')
      this.count = 1;
    }
    else{
      this.count = 0;
    }
  }

  acceptNotes(event) {
    debugger
    this.checkBox = !event.target.checked;
  }

  onEdit(){
    debugger
    this.insertLocalData()
    if(this.checkBox == true){
      // this.router.navigate(['/tabs/vasipu-iyakam/vi-session'], { queryParams: { "schoolId": this.schoolID , "userID":this.username} });
      // this.modalCtrl.dismiss();
    }
  }

  insertLocalData() {
    let insertRows = [];
    // elementData.forEach(element => {
      insertRows.push([
        "INSERT INTO VIInstructionData VALUES (?,?,?,?)",
        [null,1, this.schoolID,this.username]
      ]);
    // });
    this.sqliteDB.bulkInsert(insertRows).then((result) => {
      console.info("LocalData Stored student Locally");
      this.modalCtrl.dismiss('', 'success');
    })
  }

  closeModal(){
    this.modalCtrl.dismiss('', 'success');
  }
  
  

}
